  '緑': 'green', 'green': 'green',
  '青': 'blue', 'blue': 'blue',
  '紫': 'purple', 'purple': 'purple',
  '桃': 'pink', 'pink': 'pink', 'ピンク': 'pink', '桃色': 'pink',
