  if (!m) m = s.match(/^\u21d2\s*\{([^}]*)\}\s*$/);
  if (!m) m = s.match(/^\u21c4\s*\{([^}]*)\}\s*$/);
  if (!m) m = s.match(/^\{[^}]*\}\s*\u21d2\s*Me\s*\u21d2\s*\{([^}]*)\}\s*$/);
