  const syntax = commentSyntaxForDocument(doc);
  if (syntax === 'markdown') {
    const indent = (inner.match(/^\s*/) || [''])[0];
    const body = inner.slice(indent.length);
    return `${indent}<!-- ${body} -->`;
  }
