    const _raw3 = doc.lineAt(line).text || ''; // v4.0.223: 足切りは生の行で先に
    if (_raw3.indexOf(from) < 0) continue;
    const text = meosRefScanText(_raw3); // v4.0.215: コードスパンの中の符は触らない
    if (text.indexOf(from) < 0) continue;
