// {* ▼mCN=0865_RENAME_ME // v0.9.235 Rename Me safe implementation (📊⊕0+0D0W) [oGJF=h] [tRJF=h] *}
function membraneNameRangeForRenameOnLine(document, line, expectedKind, expectedId) {
  if (!document || line < 0 || line >= document.lineCount) return null;
  const rawLine = document.lineAt(line).text || "";
  const raw = normalizeProtoMembraneLineText(rawLine);
  const unwrapped = unwrapMembraneCommentText(raw || "");
  const text = unwrapped.inner || raw;
  const arrow = expectedKind === 'open' ? '[▼▽]' : '[▲△]';
  const key = '(?:mCN|CN|H1|H2|H3)';

  // Code / proto source:
  //   // {* ▼mCN=name // comment *}
  //   // {* ▼H1=name // comment *}
  let re = new RegExp('^(\\s*)(//[ \\t]*\\{[ \\t]*' + arrow + '[ \\t]*' + key + '[ \\t]*=[ \\t]*)([^\\r\\n]*?)(?=[ \\t]+\\/\\/|[ \\t]*\\*?\\}\\s*$|$)(.*)$');
  let m = text.match(re);

  // Markdown hidden comments:
  //   [//]: # (▼name // comment)
  //   [//]: # (▼mCN=name // comment)
  //   [//]: # (▼H1=name // comment)
  if (!m) {
    re = new RegExp('^(\\s*)(\\[\\/\\/\\]:[ \\t]*#[ \\t]*(?:(?:\\"|\\()[ \\t]*)?' + arrow + '[ \\t]*(?:' + key + '[ \\t]*=[ \\t]*)?)([^\\r\\n]*?)(?=[ \\t]+\\/\\/|[ \\t]*[\\")]|$)(.*)$');
    m = text.match(re);
  }

  if (!m) return null;

  const idText = cleanMembraneName(m[3]);
  if (!idText) return null;
  if (expectedId !== undefined && idText !== expectedId) return null;

  let idStart = m[1].length + m[2].length;
  let idEnd = idStart + idText.length;

  // Map back to the raw source line if proto normalization changed positions.
  const rawIdStart = rawLine.indexOf(idText);
  if (rawIdStart >= 0) {
    idStart = rawIdStart;
    idEnd = rawIdStart + idText.length;
  }

  return {
    id: idText,
    range: new vscode.Range(line, idStart, line, idEnd)
  };
}

// ★★v4.0.351(俊克 8/22「膜名を直接変えると、閉じ膜と違うので、おかしくなるという経験は以前から
//   経験している。でも、直接変えたくなるよね。Edit Meを使わずに、直接、膜名の編集は可能か?」):
//   ★★**可能。開始膜の名前をそのまま打ち直せばよく、閉じ膜は MeOS が後から揃える**。
//   ★揃える瞬間は**その行を離れた時の1回だけ**。打つたびに閉じ膜も書き換えると、打鍵の道に文書の編集を
//     足すことになり([[project_meos_freeze_pattern]]の穴)、取り消しも1文字ずつに割れる。
//     「行を離れたら直す」は MeOS の既定の作法(v0.9.618)。
//   ★★入った時の名前と閉じ行の番号を**先に控える**。名前を打ち替えた瞬間に対は壊れる(対は名前で照合して
//     いるので)＝ 控えが無ければ、離れた時にはもう相手が分からない。俊克の「おかしくなる」はこの状態。
//   ★閉じ行が控えた名前のままの時だけ書き換える。既に違う名前なら、誰かが直した後なので触らない。
//   ★畳んだまま名前を直すこともある(俊克「折り畳んであっても、comment1は修正できる」)＝ 閉じ行は畳んだ中に
//     居るので、書き換えると VSCode が折り畳みを計算し直して開いてしまう(v0.9.906)。**畳み直して返す**。
let _meosNameWatch = null;   // { uri, openLine, closeLine, oldName }
function meosNoteMembraneNameEdit(editor) {
  try {
    if (!editor || !editor.document || !editor.selection) return;
    const doc = editor.document;
    const uri = String(doc.uri);
    const line = editor.selection.active.line;
    const w = _meosNameWatch;
    if (w && (w.uri !== uri || w.openLine !== line)) {   // 見ていた行を離れた
      _meosNameWatch = null;
      meosApplyMembraneNameEdit(w);                      // 待たない(カーソルの道を止めない)
    }
    if (line < 0 || line >= doc.lineCount) return;
    if (_meosNameWatch && _meosNameWatch.uri === uri && _meosNameWatch.openLine === line) return; // もう見ている
    const nm = membraneNameRangeForRenameOnLine(doc, line, 'open');
    if (!nm || !nm.id) return;                           // 膜の開始行でなければ何もしない(ここで足切り)
    const pair = collectPairs(doc, { excludeIndex: false }).find(p => p.start === line && p.id === nm.id);
    if (!pair || pair.end <= pair.start) return;
    _meosNameWatch = { uri, openLine: line, closeLine: pair.end, oldName: nm.id };
  } catch (_) { }
}
// 控えと今の文書を見て、閉じ行に必要な1つの書き換えを返す(無ければ null)。判定はここ1つだけ。
function meosMembraneNameEditFor(doc, w) {
  if (!doc || !w) return null;
  if (w.openLine < 0 || w.openLine >= doc.lineCount) return null;
  if (w.closeLine <= w.openLine || w.closeLine >= doc.lineCount) return null;
  const now = membraneNameRangeForRenameOnLine(doc, w.openLine, 'open');
  if (!now || !now.id) return null;              // 開始行の形が壊れている = 触らない
  if (now.id === w.oldName) return null;         // 名前は変わっていない
  const cl = membraneNameRangeForRenameOnLine(doc, w.closeLine, 'close', w.oldName);
  if (!cl) return null;                          // 閉じ行が控えた名前でない = 触らない
  return { range: cl.range, text: now.id };
}
// 畳んだ中を書き換えると VSCode が折り畳みを計算し直して開く(v0.9.906)ので、畳み直して返す。
function meosRefoldAfterNameEdit(ed, openLine) {
  suppressViewportFoldUntil = Date.now() + 1500;
  try { if (membraneFoldingProviderInstance) membraneFoldingProviderInstance.notifyRangesChanged(); } catch (_) { }
  setTimeout(() => {
    try {
      vscode.commands.executeCommand('editor.fold', { selectionLines: [openLine] })
        .then(() => { try { refresh(ed); } catch (_) { } }, () => { });
    } catch (_) { }
  }, 220);
}
async function meosApplyMembraneNameEdit(w) {
  try {
    if (!w) return;
    const ed = vscode.window.visibleTextEditors.find(e => String(e.document.uri) === w.uri);
    if (!ed || !ed.document || ed.document.isClosed) return;
    const one = meosMembraneNameEditFor(ed.document, w);
    if (!one) return;
    const pairNow = collectPairs(ed.document, { excludeIndex: false }).find(p => p.start === w.openLine);
    const wasFolded = pairNow ? isPairFolded(ed, pairNow) : false;
    const okd = await ed.edit(e => { e.replace(one.range, one.text); }, { undoStopBefore: true, undoStopAfter: true });
    if (!okd) return;
    if (wasFolded) meosRefoldAfterNameEdit(ed, w.openLine);
    try { vscode.window.setStatusBarMessage('MeOS: closing membrane renamed → ' + one.text, 2500); } catch (_) { }
    setTimeout(() => { try { refresh(ed); } catch (_) { } }, 60);
  } catch (_) { }
}
function currentMembranePairForRename(editor) {
  if (!editor) return null;
  const doc = editor.document;
  const line = editor.selection.active.line;

  const info = membraneLineInfo(doc, line);
  if (info) {
    const pair = collectPairs(doc, { excludeIndex: false }).find(p => {
      if (info.kind === 'open') return p.start === info.line && p.id === info.id;
      return p.end === info.line && p.id === info.id;
    });
    if (pair) return pair;
  }

  return findCurrentPair(editor);   // v4.0.387: FCバッジ行もここで答えが出る(専用の枝は要らない)
}

async function renameMe() {
  const editor = vscode.window.activeTextEditor;
  if (!editor) return;

  const pair = currentMembranePairForRename(editor);
  if (!pair) {
    vscode.window.showInformationMessage('Rename Me: put the cursor inside a membrane or on its name.');
    return;
  }

  const openName = membraneNameRangeForRenameOnLine(editor.document, pair.start, 'open', pair.id);
  const closeName = membraneNameRangeForRenameOnLine(editor.document, pair.end, 'close', pair.id);
  if (!openName || !closeName) {
    vscode.window.showWarningMessage('Rename Me: matching start/end membrane name range was not found.');
    return;
  }

  const nextNameInput = await vscode.window.showInputBox({
    title: 'Rename Me',
    prompt: 'Rename this Me. Start and end membrane names will be updated together.',
    value: pair.id,
    placeHolder: 'Example: My First Me_105844.503 / 私 第一膜_105844.503'
  });
  if (nextNameInput === undefined) return;

  const nextName = normalizeMembraneId(nextNameInput);
  if (!nextName) {
    vscode.window.showWarningMessage('Rename Me: membrane name cannot be empty.');
    return;
  }
  if (nextName === pair.id) return;

  const ok = await editor.edit(edit => {
    edit.replace(closeName.range, nextName);
    edit.replace(openName.range, nextName);
  }, { undoStopBefore: true, undoStopAfter: true });

  if (ok) {
    // v0.9.387: put the cursor on the actual newly-created opener line.
    // v4.0.388: 数え方が3通りに散っていた。開始膜の行を決めるのは findNewMembraneOpenerLineAfterInsert 1つだけ。
    const openerLineNo = findNewMembraneOpenerLineAfterInsert(doc, nextName, startLine);
    editor.selection = new vscode.Selection(openerLineNo, indent.length, openerLineNo, indent.length);
    editor.revealRange(new vscode.Range(openerLineNo, 0, openerLineNo, 0), vscode.TextEditorRevealType.InCenterIfOutsideViewport);
    if (meDockPanel) meDockPanel.webview.postMessage({ type: 'setLineValue', value: String(openerLineNo + 1) });
    setTimeout(() => { refresh(editor); ensureMembraneMstatMetadata(editor); if (meDockPanel) meDockPanel.webview.postMessage({ type: 'setLineValue', value: String(openerLineNo + 1) }); }, 80);
  }
}
