lineMeter=document.getElementById('time-machine-trigger'),timeMachineTrigger=document.getElementById('time-machine-trigger'),
timeMachinePanel=document.getElementById('time-machine-panel'),timeMachineSliderReal=document.getElementById('time-machine-slider-real'),
timeMachineSliderReinc=document.getElementById('time-machine-slider-reinc'),tmWorldReal=document.getElementById('tm-world-real'),
tmWorldReinc=document.getElementById('tm-world-reinc'),timeMachineIndex=document.getElementById('time-machine-index'),timeMachineTotal=document.getElementById('time-machine-total'),
timeMachineMarksReal=document.getElementById('tm-insertion-marks-real'),timeMachineMarksReinc=document.getElementById('tm-insertion-marks-reinc'),
timeMachinePre=document.getElementById('time-machine-pre'),timeMachineClear=document.getElementById('time-machine-clear'),
histBack=document.getElementById('hist-back'),histForward=document.getElementById('hist-forward'),lineInput=document.getElementById('line-input'),
refreshBtn=document.getElementById('refresh-btn'),resetBtn=document.getElementById('reset-btn'),setBtn=document.getElementById('set-btn'),
fixedToc=document.getElementById('fixed-toc'),fixedTocName=document.getElementById('fixed-toc-name'),fixedTocBody=document.getElementById('fixed-toc-body'),
tocPinBar=document.getElementById('toc-pin-bar'),tocTabRow=document.getElementById('toc-tab-row'),tocTabConfirm=document.getElementById('toc-tab-confirm'),
tocTabConfirmMsg=document.getElementById('toc-tab-confirm-msg'),tocTabConfirmYes=document.getElementById('toc-tab-confirm-yes'),
tocTabConfirmNo=document.getElementById('toc-tab-confirm-no'),toggleEditorToc=document.getElementById('toggle-editor-toc'),
