// v0.9.664: 膜操作(Copy/Select/Duplicate)の結果を画面下部に一時トースト表示。
let meDockToastTimer=null;
function showMeDockToast(text){
  let el=document.getElementById('meos-op-toast');
  if(!el){el=document.createElement('div');el.id='meos-op-toast';el.style.cssText='position:fixed;left:50%;bottom:14px;transform:translateX(-50%);background:rgba(40,40,40,0.92);color:#fff;padding:6px 14px;border-radius:6px;font-size:12px;z-index:9999;pointer-events:none;box-shadow:0 2px 8px rgba(0,0,0,0.3);transition:opacity .2s;';
document.body.appendChild(el);}
  el.textContent='✅ '+text;el.style.opacity='1';
  if(meDockToastTimer)clearTimeout(meDockToastTimer);
  meDockToastTimer=setTimeout(()=>{if(el)el.style.opacity='0';},2000);
}
