  window.__tocChildActive=function(){
    if(!pop.classList.contains('wheel'))return null;
    const at=window.__tocChildAt||{y:0};
    const rows=pop.querySelectorAll('.toc-child-row');
    let best=null,bd=Infinity,bi=0;
    rows.forEach(function(r,i){const rc=r.getBoundingClientRect();const c=rc.top+rc.height/2;const d=Math.abs(c-at.y);if(d<bd){bd=d;
best=r;bi=i;}});
    rows.forEach(function(r){r.classList.remove('toc-child-center');});
    if(best){best.classList.add('toc-child-center');pop.__wheelIdx=bi;}
    return best;
  };
