      const ed = getMeDockTargetEditor() || vscode.window.activeTextEditor;
      if (!ed) return;
      const entries = collectDiaryEntries(ed.document);
      // v2.0.31(俊克): frontendから明示の基準点(anchor)が来ればそれを使う(右Todayに打った日付/既定=今日)。無ければ従来のdiaryAnchorDate。
      const a = (message.anchor && message.anchor.mo) ? { y: (message.anchor.y || new Date().getFullYear()), mo: message.anchor.mo, d: message.anchor.d } : diaryAnchorDate(ed);
      const aKey = a.y * 10000 + a.mo * 100 + a.d;
